        var secrets=new Secrets("synthetic-p7-operations-secret-".repeat(3));idem=new IdempotencyService(db,tx,secrets,mapper);audit=new OperationsAudit(db,mapper);ops=new OperationsService(db,tx,mapper,audit,idem,secrets);metrics=new OperationsMetrics(ops);objects=new PrivateObjectStore(folder.toRealPath().toString());exports=new AdminExportService(ops,metrics,idem,mock(RateLimits.class),objects);jobs=new AdminExportJobs(ops,exports,objects);
