    long operator(String name){db.update("INSERT INTO sys_user(user_name,nick_name,password,status,del_flag,create_by) VALUES(?,?,'not-a-login-hash','0','0','p7-operations-test')",name,name);return db.queryForObject("SELECT user_id FROM sys_user WHERE user_name=?",Long.class,name);}
