        for(var row:db.queryForList("SELECT object_key,id FROM mp_admin_export WHERE operator_id=?",operator)){objects.delete((String)row.get("object_key"));for(String checkpoint:db.queryForList("SELECT checkpoint_json FROM mp_background_job WHERE job_type='ADMIN_EXPORT' AND target_id=?",String.class,row.get("id")))try{for(var key:mapper.readTree(checkpoint).path("artifactKeys"))objects.delete(key.asText());}catch(Exception invalid){throw new IllegalStateException(invalid);}db.update("DELETE FROM mp_idempotency_record WHERE resource_type='ADMIN_EXPORT' AND resource_id=?",row.get("id"));db.update("DELETE FROM mp_admin_export_student WHERE export_id=?",row.get("id"));}
        db.update("DELETE FROM mp_background_job WHERE owner_operator_id=?",operator);db.update("DELETE FROM mp_admin_export WHERE operator_id=?",operator);db.update("DELETE FROM mp_sensitive_audit WHERE operator_id IN (?,?)",operator,other);
