        Instant at=Instant.now().minusSeconds(20*86400);long student=student(null,at.minusSeconds(60)),task=task("AI",false);long run=run(student,journey(student,at.minusSeconds(10)),task,"AI",1,at,at.plusSeconds(86400));report(student,run,at.plusSeconds(2*86400),4);String comparison=PublicIds.next();db.update("INSERT INTO mp_report(public_id,student_id,report_type,status,requested_at,ready_at,first_ready_at) VALUES(?,?,'COMPARISON','READY',?,?,?)",comparison,student,Timestamp.from(at.plusSeconds(3*86400)),Timestamp.from(at.plusSeconds(3*86400)),Timestamp.from(at.plusSeconds(3*86400)));
        var all=ops.reports(operator,OperationsQuery.parse(Map.of("studentId",publicStudent(student))));assertEquals(2,all.total());var filtered=ops.reports(operator,OperationsQuery.parse(Map.of("studentId",publicStudent(student),"majorCode","AI")));assertEquals(1,filtered.total());assertEquals("EXPERIENCE",filtered.rows().getFirst().reportType());assertTrue(filtered.scopeNotes().get(1).contains("不包含COMPARISON"));assertEquals(comparison,ops.reports(operator,OperationsQuery.parse(Map.of("studentId",publicStudent(student),"reportType","COMPARISON"))).rows().getFirst().reportId());
        var f=filters();var invalid=new OperationsDtos.Filters(f.from(),f.to(),f.asOf(),"AI",null,null,null,"COMPARISON");assertEquals("FILTER_CONFLICT",assertThrows(ApiException.class,()->exports.create(operator,key(),new OperationsDtos.ExportCreate("REPORTS",invalid,null,"Synthetic scope conflict must not enqueue"),"scope-conflict")).code);assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM mp_admin_export WHERE operator_id=?",Integer.class,operator));
